"""Audit paired offline tracking predictions; preserve original experiment artifacts."""
import argparse,json,html,os,hashlib
from pathlib import Path
from collections import Counter
from PIL import Image,ImageDraw

def main(suite,demos):
 root=Path(suite).resolve();demos=Path(demos).resolve();out=root/'analysis';out.mkdir(exist_ok=True)
 read=lambda p:json.loads(p.read_text())
 frames=read(root/'audit/frames.json');results=read(root/'evaluation/results.json');summaries=read(root/'evaluation/summary.json')
 index={(r['episode'],r['step'],r['method']):r for r in results};different=0
 for f in frames:
  source=demos/'episodes'/f['episode']/Path(f['frame']).name
  assert hashlib.sha256(source.read_bytes()).hexdigest()==f['sha256']
  pair=[index[(f['episode'],f['step'],m)] for m in ('frame_only','template_memory')]
  different+=pair[0]['selected_index']!=pair[1]['selected_index']
  for r in pair:
   eligible=f['world_present'] and f['target_index'] in [o['index'] for o in f['regions']]
   truth=(r['selected_index']==f['target_index']) if eligible else (r['selected_index'] is None if not f['world_present'] else None)
   assert r['target_eligible']==eligible and r['correct']==truth
 for s in summaries:
  rr=[r for r in results if r['method']==s['method']]
  assert s['frames']==len(rr)
  assert s['correct_present']==sum(r['correct'] is True and r['world_present'] for r in rr)
  assert s['correct_absent']==sum(r['correct'] is True and not r['world_present'] for r in rr)
 exclusions=[f for f in frames if f['world_present'] and f['target_index'] not in [o['index'] for o in f['regions']]]
 errors=[r for r in results if r['method']=='frame_only' and r['correct'] is False]
 findings=dict(frames=len(frames),paired_prediction_differences=different,errors=errors,excluded_target_frames=len(exclusions),excluded_with_projected_pixels=sum(f['target_projected_pixels']>0 for f in exclusions),episode_goal_coverage=dict(Counter(str((f['goal'],f['world_present'])) for f in frames if f['step']==0)))
 (out/'findings.json').write_text(json.dumps(findings,indent=2))
 canvas=Image.new('RGB',(1344,310),'white');draw=ImageDraw.Draw(canvas)
 for j,step in enumerate((16,24,40)):
  f=next(f for f in frames if f['episode']=='e00049' and f['step']==step)
  image=Image.open(demos/'episodes'/f['episode']/Path(f['frame']).name).convert('RGB');d=ImageDraw.Draw(image)
  for obj in f['regions']:d.rectangle(obj['bbox_raw'],outline='cyan',width=2)
  for obj in f['excluded']:d.rectangle(obj['bbox_raw'],outline='orange',width=2)
  canvas.paste(image,(448*j,30));draw.text((448*j+5,5),f'e00049 frame {step}: geometry proposals',fill='black')
 canvas.save(out/'error-context.png')
 body='''<h1>Target tracking: accurate conditional selection, no observed memory benefit</h1><p>Both methods selected the correct target on 75/76 eligible present-target frames (98.7%) and rejected all four absent-target frames. Predictions were identical on all 108 frames. No object-to-object switches were recorded; that counter ignores transitions to/from no selection, so it does not imply uninterrupted tracking.</p><table><tr><th>Coverage</th><th>Count</th></tr><tr><td>Recorded episodes / families</td><td>16 / 4</td></tr><tr><td>Present-target frames</td><td>104</td></tr><tr><td>Eligible present frames</td><td>76 (73.1%)</td></tr><tr><td>Excluded present frames</td><td>28 (26.9%)</td></tr><tr><td>Absent frames</td><td>4, one per immediately stopped teacher episode</td></tr></table><p>These are correlated teacher-trajectory frames with simulator-provided proposals. This is not 98.7% autonomous detection, navigation success, or recovery under occlusion. All 28 excluded targets have projected pixels: exclusion reflects clipping/possible HUD overlap, not proof that the target disappeared.</p>
<h2>The one error: a confidence dropout</h2><p>Episode e00049, frame 24, goal blue pillar. Both methods abstained: the target had score 0.026998, below the existing 0.05 readout threshold. Neither selected the blue arch distractor. The actual blue pillar is visible in the recorded frame. Its low score could reflect feature pooling or viewpoint sensitivity; this single example does not identify the cause.</p><img style="width:100%" src="error-context.png"><p>Cyan: accepted geometry proposals; orange: excluded proposals. At frame 40 the large, visibly present blue pillar is excluded by the conservative possible-hand/HUD filter.</p>
<h2>Why memory did not rescue it</h2><p>The implemented memory baseline only reranks candidates above the semantic threshold. Below-threshold candidates are forbidden even if their template similarity is high. Memory therefore could not rescue this dropout by construction. Identical predictions do not establish that memory is unnecessary or that temporal binding is solved.</p>
<h2>Sampling limitation</h2><p>The 12 present episodes cover four red-pillar goals, four blue-pillar goals and four red-arch goals. No present blue-arch episode was selected. All four combinations occur among absent goals. This imbalance comes from the first-N panel selection and should be corrected before the next comparison. Test geometry remains untouched.</p>
<h2>Recorded selection overlays</h2><p>Left: frame-only readout. Right: frozen template memory. Yellow is the predicted candidate, gray is other privileged proposals. These are recorded teacher movements; neither selector controlled the camera. No Q/K/V patch, Grad-CAM or attention overlay was applied.</p>'''
 for eid in ('e00048','e00049','e00050'):
  gif=root/'evaluation'/(eid+'.gif')
  body+=f'<h3>{eid}</h3><img style="max-width:100%" src="{os.path.relpath(gif,out)}"><p><code>{html.escape(os.path.relpath(gif,root.parents[2]))}</code></p>'
 body+='''<h2>Next, a targeted memory test</h2><ol><li>Balance all four present color–shape goals across validation families, retaining absent goals.</li><li>Separate initial acquisition from subsequent matching. Test template-based continuation with an explicit unknown/lost state, without granting it the true object ID or correcting wrong initial choices.</li><li>Compare clean and controlled corrupted views of the same recorded frames, with unchanged thresholds or thresholds fit only on training data. Report false persistence and wrong-object retention as well as recovered dropouts.</li><li>Use the clean-to-corrupted gap for a V30/V31 rescue diagnostic, with self-patch and unrelated-region controls. Donor-assisted rescue is not deployable performance.</li></ol><p>No new broad navigation training is warranted by this result. Image-driven localization and selector-controlled movement remain separate future gates. Keep close-up exclusions visible; do not silently count them as successes or absence.</p>'''
 body='<h1>How the red-pillar memory works</h1><p>The memory is a stored visual feature vector: a list of numbers describing the first region the model selects. It is not a saved world coordinate, object ID, image box or text string. We do not update Qwen weights or train a recurrent memory in this baseline.</p><figure style="margin:0"><a href="memory-baseline.svg"><img style="width:100%" src="memory-baseline.png" alt="Recorded red pillar across three camera views, feature template mechanism and measured results"></a><figcaption>Figure 1. Implemented frozen-template baseline. Actual frames from e00048 are annotated with recorded selections; the computational diagram is schematic. Geometry supplies candidate boxes. No benefit over frame-only selection was measured. <a href="memory-baseline.png">High-resolution PNG</a> · <a href="memory-baseline.svg">Editable vector SVG</a>.</figcaption></figure><h2>ELI5: keep a visual description, then compare</h2><ol><li>We ask for the red pillar. The frozen color/shape readout scores every proposed object region.</li><li>On the first accepted selection, copy that region’s Qwen feature vector into memory. This can be wrong; we never correct it using the true object ID.</li><li>When the camera moves, recompute candidate feature vectors at the new image locations. Compare them with the stored vector using cosine similarity.</li><li>Choose using both the current red-pillar score and resemblance to the stored appearance. If no candidate passes the current semantic threshold, choose nothing and retain the old template.</li></ol><p>The red pillar can move from the right side of the image toward the middle without its old pixel position being used for matching. Its feature vector need not stay exactly identical: similarity measures resemblance. The template may still fail under changed viewpoints, lighting or occlusion.</p><h2>Actual implementation, simplified</h2><pre>memory = None  # reset for each episode\nfor frame in sequence:\n    features = encode_and_pool(candidate_boxes)\n    scores = P(red | features) * P(pillar | features)\n    eligible = scores &gt;= 0.05\n    ranking = log(scores)\n    if memory is not None:\n        ranking += 0.5 * cosine_similarity(features, memory)\n    selected = best_eligible_candidate(ranking, eligible)\n    if memory is None and selected is not None:\n        memory = features[selected].detach().clone()\n    # No template update; no memory-specific recovery below threshold.</pre><p>Stored per episode in <code>templates[episode]</code> inside <code>src/mc_binding/target_tracking.py</code>. The helper <code>choose()</code> accepts features, semantic scores and the template—not true object IDs or poses. The diagram’s vector is symbolic because feature vectors and cosine scores were not saved in this run.</p><h2>Proposed extension — not implemented or evaluated here</h2><p><b>Acquire → track → uncertain/lost → reacquire.</b> Require reliable semantic evidence when acquiring a target. During tracking, separately test whether appearance continuity can bridge a brief semantic-score dip. If neither appearance nor current evidence supports a match, retain memory but report “lost”; do not force a match. Reacquisition must reject same-color/wrong-shape distractors and be evaluated for false persistence. Thresholds must be selected on training/development data, not adjusted to fix this one evaluation frame.</p><p>This proposal is an experiment, not a proven improvement. “Lost from view” must remain distinct from “target absent from the world.” A future adapter or recurrent memory can be trained only after these baselines reveal which failure it needs to solve.</p><hr>'+body
 (out/'explained.html').write_text('<!doctype html><meta charset="utf-8"><style>body{font:17px system-ui;line-height:1.55;max-width:1250px;margin:40px auto;padding:20px}td,th{padding:10px;border-bottom:1px solid #ddd}code{overflow-wrap:anywhere}</style>'+body)
 print(out/'explained.html')
if __name__=='__main__':
 p=argparse.ArgumentParser();p.add_argument('suite');p.add_argument('--demos',required=True);a=p.parse_args();main(a.suite,a.demos)
